import com.gymie.workout.infrastructure.presentation.web.converters.SetEffortWebConverter
import com.gymie.workout.infrastructure.presentation.web.converters.SetWeightWebConverter
import com.gymie.workout.infrastructure.presentation.web.converters.WorkoutDescriptionWebConverter
import com.gymie.workout.infrastructure.presentation.web.converters.WorkoutStatusWebConverter
import com.gymie.workout.infrastructure.presentation.web.converters.WorkoutWebConverters
import com.gymie.workout.infrastructure.presentation.web.dto.FinishReadinessResponse
import com.gymie.workout.infrastructure.presentation.web.dto.PatchWorkoutBlockRequest
import com.gymie.workout.infrastructure.presentation.web.dto.PatchWorkoutExerciseRequest
import com.gymie.workout.infrastructure.presentation.web.dto.PatchWorkoutRequest
import com.gymie.workout.infrastructure.presentation.web.dto.PatchWorkoutSetRequest
import com.gymie.workout.infrastructure.presentation.web.dto.UpdateWorkoutRequest
import com.gymie.workout.infrastructure.presentation.web.dto.WorkoutResponse
import com.gymie.workout.infrastructure.presentation.web.validators.WorkoutRequestValidator
import jakarta.validation.Valid
import org.springframework.http.HttpHeaders
import org.springframework.http.ResponseEntity
import org.springframework.security.core.Authentication
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PatchMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestHeader
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController
import java.util.UUID

/**
 * Runs the shipped `:workout` operations against a *participant's* workout while a session owner
 * holds the floor (see `group-sessions.md` R11). Every handler resolves the workout id through
 * [resolve] or [resolveForWrite] first — never from the request — so the workout acted on is
 * always the one the participant row names, and never something the client could substitute.
 * [resolve]/[resolveForWrite] are also the sole gate: they are what turns a `VIEW` viewer (403
 * `edit_access_required`) or non-participant caller (404) away before any `:workout` service ever
 * runs, and [resolveForWrite] additionally turns a lowered or revoked `WORKOUTS: EDIT` grant into `403` for every
 * write route (design § 4).
 *
 * No `start`, `delete`, `copy` or `list`: starting a participant's workout is the session's own
 * action, deleting or copying one is not the floor's concern, and the session detail already lists
 * every participant's workout.
 */
@RestController
@RequestMapping("/api/group-sessions/{id}/participants/{userId}/workout")
class GroupSessionWorkoutController(
    private val groupSessionQueryService: GroupSessionQueryService,
    private val workoutService: WorkoutService,
    private val workoutFieldPatchService: WorkoutFieldPatchService,
    private val workoutFinishReadinessService: WorkoutFinishReadinessService,
    private val responses: WorkoutResponseAssembler,
) {
    @GetMapping
    fun get(
        authentication: Authentication,
        @PathVariable id: UUID,
        @PathVariable userId: UUID,
    ): ResponseEntity<WorkoutResponse> {
        val workoutId = resolve(authentication, id, userId)
        val detail = workoutService.getDetail(userId, workoutId)
        return ResponseEntity
            .ok()
            .eTag(ETagWebConverter.toETag(detail.workout.audit.structureUpdatedAt))
            .body(responses.respond(detail.workout, detail.previous))
    }

    @PutMapping
    fun update(
        authentication: Authentication,
        @PathVariable id: UUID,
        @PathVariable userId: UUID,
        @RequestHeader(HttpHeaders.IF_MATCH, required = false) ifMatch: String?,
        @Valid @RequestBody request: UpdateWorkoutRequest,
    ): ResponseEntity<WorkoutResponse> {
        val workoutId = resolveForWrite(authentication, id, userId)
        WorkoutRequestValidator.validate(request.blocks, request.scheduledTime)
        val updated =
            workoutService.update(
                userId = userId,
                id = workoutId,
                scheduledDate = requireNotNull(request.scheduledDate),
                scheduledTime = ScheduledTimeWebConverter.toDomain(request.scheduledTime),
                description = WorkoutDescriptionWebConverter.toDomain(request),
                blocks = WorkoutWebConverters.toBlocks(request.blocks),
                status = WorkoutStatusWebConverter.toDomain(request.status),
                expectedUpdatedAt = ETagWebConverter.toExpectedUpdatedAt(ifMatch),
            )
        return ResponseEntity
            .ok()
            .eTag(ETagWebConverter.toETag(updated.audit.structureUpdatedAt))
            .body(responses.respond(updated))
    }

    @PatchMapping
    fun patchNotes(
        authentication: Authentication,
        @PathVariable id: UUID,
        @PathVariable userId: UUID,
        @RequestBody request: PatchWorkoutRequest,
    ): WorkoutResponse {
        val workoutId = resolveForWrite(authentication, id, userId)
        val scheduledTime = request.scheduledTime?.let { ScheduledTimeWebConverter.toDomain(it.orElse(null)) }
        val updated =
            workoutFieldPatchService.patchNotesAndScheduledTime(
                userId,
                workoutId,
                request.notes,
                scheduledTime,
                request.scheduledTime != null,
            )
        return responses.respond(updated)
    }

    @PatchMapping("/blocks/{blockId}")
    fun patchBlock(
        authentication: Authentication,
        @PathVariable id: UUID,
        @PathVariable userId: UUID,
        @PathVariable blockId: UUID,
        @RequestBody request: PatchWorkoutBlockRequest,
    ): WorkoutResponse {
        val workoutId = resolveForWrite(authentication, id, userId)
        val updated = workoutFieldPatchService.patchBlock(userId, workoutId, blockId, request.collapsed, request.completed)
        return responses.respond(updated)
    }

    @PatchMapping("/exercises/{exerciseId}")
    fun patchExercise(
        authentication: Authentication,
        @PathVariable id: UUID,
        @PathVariable userId: UUID,
        @PathVariable exerciseId: UUID,
        @RequestBody request: PatchWorkoutExerciseRequest,
    ): WorkoutResponse {
        val workoutId = resolveForWrite(authentication, id, userId)
        val updated =
            workoutFieldPatchService.patchExercise(
                userId,
                workoutId,
                exerciseId,
                request.note,
                request.evaluation,
                request.evaluationNote,
            )
        return responses.respond(updated)
    }

    @PatchMapping("/sets/{setId}")
    fun patchSet(
        authentication: Authentication,
        @PathVariable id: UUID,
        @PathVariable userId: UUID,
        @PathVariable setId: UUID,
        @RequestBody request: PatchFloorSetRequest,
    ): WorkoutResponse {
        val workoutId = resolveForWrite(authentication, id, userId)
        val expected =
            request.expected?.let {
                SetValues(
                    SetWeightWebConverter.toDomain(it.weight),
                    SetEffortWebConverter.toDomain(it.effort),
                    it.confirmed,
                )
            }
        val updated =
            workoutFieldPatchService.patchSet(
                userId,
                workoutId,
                setId,
                SetWeightWebConverter.toDomain(request.weight),
                SetEffortWebConverter.toDomain(request.effort),
                request.confirmed,
                actorId = UUID.fromString(authentication.name),
                expected = expected,
            )
        return responses.respond(updated)
    }

    @PostMapping("/finish")
    fun finish(
        authentication: Authentication,
        @PathVariable id: UUID,
        @PathVariable userId: UUID,
    ): WorkoutResponse = responses.respond(workoutService.finish(userId, resolveForWrite(authentication, id, userId)))

    @GetMapping("/finish-readiness")
    fun finishReadiness(
        authentication: Authentication,
        @PathVariable id: UUID,
        @PathVariable userId: UUID,
    ): FinishReadinessResponse =
        WorkoutWebConverters.toFinishReadinessResponse(
            workoutFinishReadinessService.finishReadiness(userId, resolve(authentication, id, userId)),
        )

    /**
     * The workout id for [userId] within group session [id], resolved through the session's own
     * access rules — never named by the client. Refuses a `VIEW` viewer with
     * [com.gymie.groupsession.core.exceptions.GroupSessionForbiddenException] (403
     * `edit_access_required`), and a non-participant caller, non-participant [userId] or missing
     * session with [com.gymie.groupsession.core.exceptions.GroupSessionNotFoundException] (404).
     */
    private fun resolve(
        authentication: Authentication,
        id: UUID,
        userId: UUID,
    ): UUID = groupSessionQueryService.participantWorkoutId(UUID.fromString(authentication.name), id, userId)

    /**
     * As [resolve], plus the live-grant check (design § 4): a participant who has lowered or revoked the
     * owner's `WORKOUTS: EDIT` grant mid-session answers `403` on every write route from here on, even
     * though [resolve] would still find the row.
     */
    private fun resolveForWrite(
        authentication: Authentication,
        id: UUID,
        userId: UUID,
    ): UUID = groupSessionQueryService.participantWorkoutIdForWrite(UUID.fromString(authentication.name), id, userId)
}

